public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Creates a business chat link for the current account. Requires Telegram Business subscription. There can be up to getOption("business_chat_link_count_max") links created. Returns the created link
    /// </summary>
    public Task<TdLib.TdApi.Objects.BusinessChatLink> CreateBusinessChatLinkAsync(InputBusinessChatLink linkInfo = default)
    {

           using var activity =  StartCallActivity("CreateBusinessChatLinkAsync", typeof(CreateBusinessChatLink).FullName ?? "CreateBusinessChatLinkAsync");

           try
           {
             return client.CreateBusinessChatLinkAsync(linkInfo);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
